// At bundle boot — show only buttons the manifest actually grants.
const { tools } = await anna.tools.list();
const allowed = new Set(tools.map(t => t.tool_id));

for (const btn of document.querySelectorAll('[data-tool]')) {
  if (!allowed.has(btn.dataset.tool)) btn.hidden = true;
}

// bundle/app.js — call a server-minted focus-session tool.
const TOOL_ID = "tool-test-focus-session-12345678";
const TOOL_METHOD = "session_action";

try {
  const result = await anna.tools.invoke({
    tool_id: TOOL_ID,
    method:  TOOL_METHOD,
    args:    { action: "start", duration_min: 25 },
    timeoutMs: 60_000,            // within the 1 s–90 s clamp, so passed through as-is
  });
  applyState(result);             // plugin payload, envelopes stripped
} catch (e) {
  switch (e.code) {
    case "tool_timeout":          setStatus("plugin took too long");  break;
    case "agent_unavailable":     setStatus("agent is offline");      break;
    case "permission_denied":     setStatus("tool not whitelisted");  break;
    case "tool_failed":           setStatus(`plugin: ${e.message}`);  break;
    default:                       throw e;
  }
}

// The high-level wrapper is what most apps want:
const ctl = new AbortController();
cancelBtn.onclick = () => ctl.abort();

const result = await anna.tools.invokeAsyncAwait(
  {
    tool_id: TOOL_ID,
    method: "run_steps",
    args: { steps: 100 },
    timeoutMs: 30 * 60_000,      // job deadline
    clientTag: "render-batch-7", // reload-recovery key
  },
  {
    onProgress: (ev) => bar.update(ev.data),  // {seq, type, data}
    signal: ctl.signal,                        // abort → cancelJob
  },
);
// rejects with err.code ∈ tool_failed | tool_timeout | cancelled |
// wait_timeout (err.jobId lets you recover) | job_quota_exceeded | …

// Incremental poll loop (what invokeAsyncAwait does internally):
let seq = 0;
for (;;) {
  const snap = await anna.tools.getJob({ jobId, sinceSeq: seq });
  snap.progress.forEach(renderProgress);      // [{seq, ts, type, data}]
  if (snap.progress.length) seq = snap.lastSeq;
  if (["succeeded","failed","cancelled","expired"].includes(snap.state)) {
    if (snap.state === "succeeded") return snap.result;
    throw Object.assign(new Error(snap.error.message), snap.error);
  }
  await sleep(2000);
}

// AbortSignal wiring (invokeAsyncAwait does this for you):
const out = await anna.tools.cancelJob({ jobId, reason: "user clicked stop" });
if (!out.cancelled) console.log(`already terminal: ${out.state}`);

// Reload recovery (see the anna-app-long-task-demo example):
const { jobs } = await anna.tools.listJobs({
  clientTag: "render-batch-7",
  state: ["queued", "running"],
});
for (const job of jobs) adoptJob(job.jobId, job.lastSeq);
